	@Test
	void interveningHistoryOwnsCapturedModelUntilObserverCloses() {
		TrackingFactory models = new TrackingFactory();
		try (SailSourceBranch branch = branch(new RecordingSource(), models);
				SailSink observer = branch.sink(IsolationLevels.SERIALIZABLE)) {
			Statement x = statement("x");
			try (SailDataset originalView = branch.dataset(IsolationLevels.NONE)) {
				assertTrue(read(originalView).isEmpty(), "the observation is made before the competing publication");
			}
			observer.observe(x.getSubject(), x.getPredicate(), x.getObject());
			write(branch, x);
			TrackingModel captured = models.onlyModel();
			try (SailSource.FlushBatch batch = branch.freezeForFlush()) {
				batch.flush();
				batch.unFreezeAndDiscardFlushed();
				assertEquals(0, captured.closes, "the original observer still owns the intervening history");
				assertThrows(SailConflictException.class, observer::prepare);
				assertEquals(0, captured.closes, "failed preparation does not retire the original read boundary");
			}
			observer.close();
			assertEquals(1, captured.closes);
		}
	}

