	@Test
	void nestedSharedModelCleanupWaitsForPreparedReservationRelease() throws Exception {
		TrackingFactory models = new TrackingFactory();
		ReservationSource backing = new ReservationSource();
		try (ExecutorService executor = Executors.newSingleThreadExecutor();
				SailSourceBranch parent = branch(backing, models);
				SailSource child = parent.fork()) {
			write(child, statement("x"));
			TrackingModel captured = models.onlyModel();
			child.prepare();
			assertTrue(backing.preparedReservations.get() > 0, "parent preparation holds a real backing reservation");
			captured.onClose = () -> {
				assertEquals(0, backing.preparedReservations.get(), "final model cleanup follows preparation release");
				try {
					executor.submit(() -> {
						try (SailSink fresh = parent.sink(IsolationLevels.NONE)) {
							fresh.prepare();
						}
					}).get(5, TimeUnit.SECONDS);
				} catch (Exception failure) {
					throw new AssertionError("physical cleanup retained a prepared parent reservation", failure);
				}
			};
			try (SailSource.FlushBatch batch = child.freezeForFlush()) {
				batch.flush();
				batch.unFreezeAndDiscardFlushed();
			}
			assertEquals(1, captured.closes, "all nested shallow owners release the one shared physical model");
			assertEquals(0, backing.preparedReservations.get());
		}
	}

