	@Test
	void plainModelReadCallbackDrainsDeferredCleanupAtReaderBoundary() {
		TrackingFactory victimModels = new TrackingFactory();
		Changeset victim = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return victimModels.createEmptyModel();
			}
		};
		Statement victimStatement = statement("callback-victim");
		victim.approve(victimStatement);
		TrackingModel victimModel = victimModels.onlyModel();

		CallbackTrackingModel queryModel = new CallbackTrackingModel();
		Changeset query = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return queryModel;
			}
		};
		Statement queryStatement = statement("callback-query");
		query.approve(queryStatement);
		AtomicBoolean callbackFired = new AtomicBoolean();
		queryModel.onPatternContains = () -> {
			callbackFired.set(true);
			assertEquals(0, victimModel.closes, "the query's outer reader guard delays nested cleanup");
			victim.close();
			assertEquals(0, victimModel.closes, "nested cleanup stays deferred until the query returns");
		};
		queryModel.patternCallbackEnabled = true;

		try (victim; query) {
			assertTrue(query.hasApproved(queryStatement.getSubject(), queryStatement.getPredicate(),
					queryStatement.getObject(), new Resource[0]));
			assertTrue(callbackFired.get(), "the actual model pattern lookup invoked the nested close callback");
			assertEquals(1, victimModel.closes,
					"the reader boundary drains cleanup deferred by the model callback before returning; callbackFired="
							+ callbackFired.get());
		}
	}

	@Test
	void plainModelReadPreservesPrimaryFailureWhenDeferredCleanupAlsoFails() {
		TrackingFactory victimModels = new TrackingFactory();
		Changeset victim = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return victimModels.createEmptyModel();
			}
		};
		victim.approve(statement("callback-failure-victim"));
		TrackingModel victimModel = victimModels.onlyModel();
		SailException cleanupFailure = new SailException("injected deferred model cleanup failure");
		victimModel.onClose = () -> {
			throw cleanupFailure;
		};

		CallbackTrackingModel queryModel = new CallbackTrackingModel();
		Changeset query = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return queryModel;
			}
		};
		Statement queryStatement = statement("callback-failure-query");
		query.approve(queryStatement);
		RuntimeException primaryFailure = new IllegalStateException("injected model lookup failure");
		AtomicBoolean callbackFired = new AtomicBoolean();
		queryModel.onPatternContains = () -> {
			callbackFired.set(true);
			assertEquals(0, victimModel.closes);
			victim.close();
			assertEquals(0, victimModel.closes);
			throw primaryFailure;
		};
		queryModel.patternCallbackEnabled = true;

		try (victim; query) {
			RuntimeException thrown = assertThrows(RuntimeException.class,
					() -> query.hasApproved(queryStatement.getSubject(), queryStatement.getPredicate(),
							queryStatement.getObject(), new Resource[0]));
			assertSame(primaryFailure, thrown);
			assertTrue(callbackFired.get(), "the injected delegate failure came from the actual model lookup");
			assertEquals(1, victimModel.closes);
			assertEquals(1, primaryFailure.getSuppressed().length);
			assertSame(cleanupFailure, primaryFailure.getSuppressed()[0]);
		}
	}

	@Test
	void sinkObservedCallbackDrainsDeferredCleanupAtReaderBoundary() {
		TrackingFactory victimModels = new TrackingFactory();
		Changeset victim = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return victimModels.createEmptyModel();
			}
		};
		victim.approve(statement("sink-observed-victim"));
		TrackingModel victimModel = victimModels.onlyModel();

		Changeset observed = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return new LinkedHashModel();
			}
		};
		Statement pattern = statement("sink-observed-pattern");
		observed.observe(pattern.getSubject(), pattern.getPredicate(), pattern.getObject());
		AtomicBoolean callbackFired = new AtomicBoolean();
		Changeset destination = new Changeset() {
			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return new LinkedHashModel();
			}

			@Override
			public void observeAll(Set<SimpleStatementPattern> patterns) {
				callbackFired.set(true);
				assertEquals(0, victimModel.closes, "the observed carrier's reader guard defers nested cleanup");
				victim.close();
				assertEquals(0, victimModel.closes, "nested cleanup stays deferred while sinkObserved is active");
				super.observeAll(patterns);
			}
		};

		try (victim; observed; destination) {
			observed.sinkObserved(destination);
			assertTrue(callbackFired.get(), "sinkObserved called the destination's actual observeAll callback");
			assertEquals(1, victimModel.closes,
					"sinkObserved drains nested cleanup before returning; callbackFired=" + callbackFired.get());
		}
	}

	@Test
	void unrelatedModelCleanupWaitsForPreparedContinuationAndRunsAfterReservationRelease() {
		TrackingFactory models = new TrackingFactory();
		ReservationSource backing = new ReservationSource();
		try (SailSourceBranch branch = branch(backing, models);
				SailSink original = branch.sink(IsolationLevels.SERIALIZABLE)) {
			original.observe(null, null, null);
			original.prepare();
			assertEquals(1, backing.preparedReservations.get(), "the original sink holds a real native reservation");

			Changeset unrelated = new Changeset() {
				@Override
				public void flush() {
				}

				@Override
				public Model createEmptyModel() {
					return models.createEmptyModel();
				}
			};
			unrelated.approve(statement("unrelated-direct-changeset"));
			TrackingModel captured = models.onlyModel();
			captured.onClose = () -> assertEquals(0, backing.preparedReservations.get(),
					"the physical model closes only after the original backing reservation is released");
			unrelated.close();
			assertEquals(0, captured.closes,
					"an unrelated model close is deferred while the original prepared continuation owns cleanup");

			try (SailWriteContinuation.Suspension ignored = SailWriteContinuation.suspend(backing.reservationLock)) {
				assertFalse(backing.reservationLock.isLocked(),
						"the continuation suspends its native reservation lock");
				Changeset empty = new Changeset() {
					@Override
					public void flush() {
					}

					@Override
					public Model createEmptyModel() {
						return models.createEmptyModel();
					}
				};
				empty.close();
				assertEquals(0, captured.closes,
						"closing an empty changeset inside the suspension does not drain prepared cleanup");
			}

			assertEquals(0, captured.closes, "resuming the continuation retains its pending model cleanup");
			original.releasePrepared();
			assertEquals(0, backing.preparedReservations.get());
			assertEquals(1, captured.closes, "the deferred model is closed once after the reservation is released");
		}
	}

	private static SailSourceBranch branch(SailSource source, ModelFactory models) {
		return new SailSourceBranch(source, models, false);
	}

	private static void write(SailSource source, Statement... statements) {
		try (SailSink sink = source.sink(IsolationLevels.NONE)) {
			for (Statement statement : statements) {
				sink.approve(statement);
			}
			sink.flush();
		}
	}

	private static Statement statement(String value) {
		var vf = SimpleValueFactory.getInstance();
		return vf.createStatement(vf.createIRI("urn:owned:" + value), vf.createIRI("urn:owned:p"),
				vf.createLiteral(value));
	}

	private static List<Statement> read(SailDataset dataset) {
		try (CloseableIteration<? extends Statement> cursor = dataset.getStatements(null, null, null)) {
			List<Statement> rows = new ArrayList<>();
			while (cursor.hasNext()) {
				rows.add(cursor.next());
			}
			return rows;
		}
	}

	private static final class TrackingFactory implements ModelFactory {
		private final List<TrackingModel> models = new ArrayList<>();

		@Override
		public Model createEmptyModel() {
			TrackingModel model = new TrackingModel();
			models.add(model);
			return model;
		}

		private TrackingModel onlyModel() {
			assertEquals(1, models.size(), "the fixture uses exactly one physical statement model");
			return models.get(0);
		}
	}

	private static class TrackingModel extends LinkedHashModel implements AutoCloseable {
		private int closes;
		private Runnable onClose = () -> {
		};

		@Override
		public void close() {
			closes++;
			onClose.run();
		}
	}

	private static final class CallbackTrackingModel extends TrackingModel {
		private Runnable onPatternContains = () -> {
		};
		private boolean patternCallbackEnabled;

		@Override
		public boolean contains(Resource subj, IRI pred, Value obj, Resource... contexts) {
			if (patternCallbackEnabled) {
				onPatternContains.run();
			}
			return super.contains(subj, pred, obj, contexts);
		}
	}

	private static final class ReservationSource extends RecordingSource {
		private final AtomicInteger preparedReservations = new AtomicInteger();
		private final ReentrantLock reservationLock = new ReentrantLock();

		@Override
		public SailClosable beginPreparedWrite() {
			reservationLock.lock();
			preparedReservations.incrementAndGet();
			AtomicBoolean released = new AtomicBoolean();
			return () -> {
				if (released.compareAndSet(false, true)) {
					preparedReservations.decrementAndGet();
					reservationLock.unlock();
				}
			};
		}
	}

	private static class RecordingSource extends BackingSailSource {
		private final List<Statement> committed;

		private RecordingSource(Statement... committed) {
			this.committed = Arrays.asList(committed);
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new SailDataset() {
				@Override
				public void close() {
				}

				@Override
				public CloseableIteration<? extends Namespace> getNamespaces() {
					return new EmptyIteration<>();
				}

				@Override
				public String getNamespace(String prefix) {
					return null;
				}

				@Override
				public CloseableIteration<? extends Resource> getContextIDs() {
					return new EmptyIteration<>();
				}

				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
						Resource... contexts) {
					return new CloseableIteratorIteration<>(committed.stream()
							.filter(st -> (s == null || s.equals(st.getSubject()))
									&& (p == null || p.equals(st.getPredicate()))
									&& (o == null || o.equals(st.getObject())))
							.iterator());
				}
			};
		}

		@Override
		public SailSink sink(IsolationLevel level) {
			return new SailSink() {
				@Override
				public void prepare() {
				}

				@Override
				public void flush() {
				}

				@Override
				public void close() {
				}

				@Override
				public void setNamespace(String prefix, String name) {
				}

				@Override
				public void removeNamespace(String prefix) {
				}

				@Override
				public void clearNamespaces() {
				}

				@Override
				public void clear(Resource... contexts) {
				}

				@Override
				public void observe(Resource s, IRI p, Value o, Resource... contexts) {
				}

				@Override
				public void approve(Resource s, IRI p, Value o, Resource c) {
				}

				@Override
				public void deprecate(Statement statement) {
				}
			};
		}
	}
